func requireManifestAssertion(t *testing.T, expected manifestAssertion, assertion string, publicKey *rsa.PublicKey) {
	t.Helper()
	segments := strings.Split(assertion, ".")
	require.Len(t, segments, 3)
	signature, err := base64.RawURLEncoding.DecodeString(segments[2])
	require.NoError(t, err)
	digest := sha256.Sum256([]byte(segments[0] + "." + segments[1]))
	require.NoError(t, rsa.VerifyPKCS1v15(publicKey, crypto.SHA256, digest[:], signature), "the stored private key signs the assertion")
	payload, err := base64.RawURLEncoding.DecodeString(segments[1])
	require.NoError(t, err)
	var claims map[string]any
	require.NoError(t, json.Unmarshal(payload, &claims))
	require.Equal(t, expected.issuer, claims["iss"], "issuer")
	require.Equal(t, expected.audience, claims["aud"], "audience")
	if expected.subject == "" {
		require.NotContains(t, claims, "sub")
	} else {
		require.Equal(t, expected.subject, claims["sub"], "subject")
	}
	if expected.scope == "" {
		require.NotContains(t, claims, "scope")
	} else {
		require.Equal(t, expected.scope, claims["scope"], "scope")
	}
	issuedAt, isNumber := claims["iat"].(float64)
	require.True(t, isNumber)
	expiresAt, isNumber := claims["exp"].(float64)
	require.True(t, isNumber)
	require.Equal(t, expected.lifetime, time.Duration(expiresAt-issuedAt)*time.Second, "lifetime")
}

